  `kd_daya_terpasang2` varchar(2) DEFAULT NULL,
  `kd_daya_terpasang3` varchar(2) DEFAULT NULL,
  `kode_pelanggan_daya` varchar(16) DEFAULT NULL,
  `kd_bahan_bakar_memasak` varchar(2) DEFAULT NULL,
  `kd_fasilitas_tempat_bab` varchar(2) DEFAULT NULL,
  `kd_jenis_kloset` varchar(2) DEFAULT NULL,
  `kd_pembuangan_akhir_tinja` varchar(2) DEFAULT NULL,
