  `kd_tabung_gas_5_5_kg` varchar(2) DEFAULT NULL,
  `kd_tabung_gas_12_kg` varchar(2) DEFAULT NULL,
  `kd_lemari_es` varchar(2) DEFAULT NULL,
  `kd_ac` varchar(2) DEFAULT NULL,
  `kd_pemanas_air` varchar(2) DEFAULT NULL,
  `kd_telepon_rumah` varchar(2) DEFAULT NULL,
  `kd_televisi` varchar(2) DEFAULT NULL,
  `kd_perhiasan_10_gr_emas` varchar(2) DEFAULT NULL,
  `kd_rek_aktif` varchar(2) DEFAULT NULL,
  `kd_komputer_laptop` varchar(2) DEFAULT NULL,
  `kd_sepeda_motor` varchar(2) DEFAULT NULL,
  `kd_mobil` varchar(2) DEFAULT NULL,
  `kd_perahu` varchar(2) DEFAULT NULL,
  `kd_kapal_perahu_motor` varchar(2) DEFAULT NULL,
  `kd_featured_phone` varchar(2) DEFAULT NULL,
  `kd_smartphone` varchar(2) DEFAULT NULL,
  `kd_sepeda` varchar(2) DEFAULT NULL,
  `kd_lahan` varchar(2) DEFAULT NULL,
