  `kd_ada_sertiv_lahan` varchar(2) DEFAULT NULL,
  `kd_rumah_ditempat_lain` varchar(2) DEFAULT NULL,
  `jumlah_sapi` int(2) DEFAULT NULL,
  `jumlah_kerbau` int(2) DEFAULT NULL,
  `jumlah_kuda` int(2) DEFAULT NULL,
  `jumlah_babi` int(2) DEFAULT NULL,
  `jumlah_kambing_domba` int(2) DEFAULT NULL,
  `jumlah_unggas` int(2) DEFAULT NULL,
  `jumlah_ikan` int(2) DEFAULT NULL,
  `jumlah_lainnya` int(2) DEFAULT NULL,
  `kd_ada_art_usaha_sendiri_bersama` varchar(2) DEFAULT NULL,
  `kd_internet_sebulan` varchar(2) DEFAULT NULL,
  `kd_pengeluaran_pulsa_dan_data` varchar(2) DEFAULT NULL,
  `kd_ada_art_lanjut_usia` varchar(2) DEFAULT NULL,
  `kd_bss_bnpt` varchar(2) DEFAULT NULL,
