  `kd_blt_dana_desa` varchar(2) DEFAULT NULL,
  `bulan_blt_dana_desa` varchar(2) DEFAULT NULL,
  `tahun_blt_dana_desa` year(4) DEFAULT NULL,
  `kd_subsidi_listrik` varchar(2) DEFAULT NULL,
  `bulan_subsidi_listrik` varchar(2) DEFAULT NULL,
  `tahun_subsidi_listrik` year(4) DEFAULT NULL,
  `kd_asuransi_lain` varchar(2) DEFAULT NULL,
  `bulan_asuransi_lain` varchar(2) DEFAULT NULL,
  `tahun_asuransi_lain` year(4) DEFAULT NULL,
  `kd_bantuan_pemprov` varchar(2) DEFAULT NULL,
  `bulan_bantuan_pemprov` varchar(2) DEFAULT NULL,
  `tahun_bantuan_pemprov` year(4) DEFAULT NULL,
  `kd_bantuan_pemkabkot` varchar(2) DEFAULT NULL,
  `bulan_bantuan_pemkabkot` varchar(2) DEFAULT NULL,
  `tahun_bantuan_pemkabkot` year(4) DEFAULT NULL,
  `kd_bantuan_pemdes` varchar(2) DEFAULT NULL,
  `bulan_bantuan_pemdes` varchar(2) DEFAULT NULL,
  `tahun_bantuan_pemdes` year(4) DEFAULT NULL,
  `kd_bantuan_pemda` varchar(2) DEFAULT NULL,
  `bulan_bantuan_pemda` varchar(2) DEFAULT NULL,
  `tahun_bantuan_pemda` year(4) DEFAULT NULL,
  `kd_bantuan_masyarakat` varchar(2) DEFAULT NULL,
  `bulan_bantuan_masyarakat` varchar(2) DEFAULT NULL,
  `tahun_bantuan_masyarakat` year(4) DEFAULT NULL,
  `kd_subsidi_pupuk` varchar(2) DEFAULT NULL,
  `bulan_subsidi_pupuk` varchar(2) DEFAULT NULL,
  `tahun_subsidi_pupuk` year(4) DEFAULT NULL,
  `kd_subsidi_lpg` varchar(2) DEFAULT NULL,
  `bulan_subsidi_lpg` varchar(2) DEFAULT NULL,
  `tahun_subsidi_lpg` year(4) DEFAULT NULL,
  `kd_konsumsi_daging` varchar(2) DEFAULT NULL,
  `kd_makan` varchar(2) DEFAULT NULL,
  `kd_beli_pakaian_baru` varchar(2) DEFAULT NULL,
  `kd_bayar_biaya_pengobatan` varchar(2) DEFAULT NULL,
  `kd_bahasa_wawancara` varchar(2) DEFAULT NULL,
  `tulis_bahasa_daerah` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK_dtks_rtm` (`id_rtm`),
  KEY `FK_kel_dtks` (`id_keluarga`),
  KEY `dtks_config_fk` (`config_id`),
  CONSTRAINT `FK_dtks_rtm` FOREIGN KEY (`id_rtm`) REFERENCES `tweb_rtm` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_kel_dtks` FOREIGN KEY (`id_keluarga`) REFERENCES `tweb_keluarga` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `dtks_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: dtks_anggota
#

DROP TABLE IF EXISTS `dtks_anggota`;

CREATE TABLE `dtks_anggota` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_dtks` int(11) DEFAULT NULL,
  `id_penduduk` int(11) DEFAULT NULL,
  `id_keluarga` int(10) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `kd_ket_keberadaan_art` varchar(2) DEFAULT NULL,
  `bulan_meninggal` varchar(2) DEFAULT NULL,
  `tahun_meninggal` year(4) DEFAULT NULL,
  `kd_punya_akta_meniggal` varchar(2) DEFAULT NULL,
  `bulan_pindah_tempat` varchar(2) DEFAULT NULL,
  `tahun_pindah_tempat` year(4) DEFAULT NULL,
  `kd_tempat_tinggal_saat_ini` varchar(2) DEFAULT NULL,
  `bulan_masuk_ruta` varchar(2) DEFAULT NULL,
  `tahun_masuk_ruta` year(4) DEFAULT NULL,
  `kd_alasan_masuk_ruta` varchar(2) DEFAULT NULL,
  `kd_hubungan_dg_krt` varchar(2) DEFAULT NULL,
  `kd_hubungan_dg_kk` varchar(2) DEFAULT NULL,
  `kd_jenis_kelamin` varchar(2) DEFAULT NULL,
  `kd_punya_aktanikah_cerai` varchar(2) DEFAULT NULL,
  `kd_punya_kartuid` varchar(2) DEFAULT NULL,
  `kd_sulit_penglihatan` varchar(2) DEFAULT NULL,
  `kd_sulit_pendengaran` varchar(2) DEFAULT NULL,
  `kd_sulit_jalan_naiktangga` varchar(2) DEFAULT NULL,
  `kd_sulit_gerak_tangan_jari` varchar(2) DEFAULT NULL,
  `kd_sulit_belajar_intelektual` varchar(2) DEFAULT NULL,
  `kd_sulit_ingat_konsentrasi` varchar(2) DEFAULT NULL,
  `kd_sulit_perilaku_emosi` varchar(2) DEFAULT NULL,
  `kd_sulit_paham_bicara_kom` varchar(2) DEFAULT NULL,
  `kd_sulit_mandiri` varchar(2) DEFAULT NULL,
  `kd_sering_sedih_depresi` varchar(2) DEFAULT NULL,
  `kd_memiliki_perawat` varchar(2) DEFAULT NULL,
  `kd_merokok_sebulan_akhir` varchar(2) DEFAULT NULL,
  `kd_penyakit_kronis_menahun` varchar(2) DEFAULT NULL,
  `kd_partisipasi_sekolah` varchar(2) DEFAULT NULL,
  `kd_pendidikan_tertinggi` varchar(2) DEFAULT NULL,
  `kd_kelas_tertinggi` varchar(2) DEFAULT NULL,
  `kd_ijazah_tertinggi` varchar(2) DEFAULT NULL,
  `kd_bekerja_seminggu_lalu` varchar(2) DEFAULT NULL,
  `jumlah_jam_kerja_seminggu_lalu` varchar(2) DEFAULT NULL,
  `pendapatan_sebulan_terakhir` bigint(14) DEFAULT NULL,
  `kd_punya_npwp` varchar(2) DEFAULT NULL,
  `npwp` varchar(15) DEFAULT NULL,
  `kd_lapangan_usaha_pekerjaan` varchar(2) DEFAULT NULL,
  `kd_kedudukan_di_pekerjaan` varchar(2) DEFAULT NULL,
  `kd_gizi_seimbang` varchar(2) DEFAULT NULL,
  `kd_imunasasi_lengkap` varchar(2) DEFAULT NULL,
  `kd_bantuan_pempus` varchar(2) DEFAULT NULL,
  `kd_bantuan_pemkot` varchar(2) DEFAULT NULL,
  `kd_bantuan_pemdes` varchar(2) DEFAULT NULL,
  `kd_jamkes_setahun` varchar(2) DEFAULT NULL,
  `kd_ikut_pbijkn_bpjssehat` varchar(2) DEFAULT NULL,
  `kd_ikut_bpjssehat_nonpbi` varchar(2) DEFAULT NULL,
  `kd_ikut_jamsostek_bpjsk` varchar(2) DEFAULT NULL,
  `kd_ikut_pip` varchar(2) DEFAULT NULL,
  `kd_ikut_prakerja` varchar(2) DEFAULT NULL,
  `kd_ikut_kur` varchar(2) DEFAULT NULL,
  `kd_ikut_umi` varchar(2) DEFAULT NULL,
  `jumlah_jamket_kerja` varchar(2) DEFAULT NULL,
  `is_usaha_sendiri_bersama` tinyint(1) NOT NULL DEFAULT '0',
  `kd_punya_usaha_sendiri_bersama` varchar(2) DEFAULT NULL,
  `jumlah_usaha_sendiri_bersama` tinyint(2) DEFAULT NULL,
  `kd_lapangan_usaha_dr_usaha` varchar(2) DEFAULT NULL,
  `tulis_lapangan_usaha_dr_usaha` varchar(191) NOT NULL DEFAULT '',
  `tulis_lapangan_usaha_pekerjaan` varchar(191) NOT NULL DEFAULT '',
  `jumlah_pekerja_dibayar` tinyint(3) DEFAULT NULL,
  `jumlah_pekerja_tidak_dibayar` tinyint(2) DEFAULT NULL,
  `kd_kepemilikan_ijin_usaha` varchar(2) DEFAULT NULL,
  `kd_omset_usaha_perbulan` varchar(2) DEFAULT NULL,
  `kd_guna_internet_usaha` varchar(2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK_dtks_dtks_anggota` (`id_dtks`),
  KEY `FK_pend_dtks_anggota` (`id_penduduk`),
  KEY `FK_kel_dtks_anggota` (`id_keluarga`),
  KEY `dtks_anggota_config_fk` (`config_id`),
  CONSTRAINT `FK_dtks_dtks_anggota` FOREIGN KEY (`id_dtks`) REFERENCES `dtks` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_kel_dtks_anggota` FOREIGN KEY (`id_keluarga`) REFERENCES `tweb_keluarga` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_pend_dtks_anggota` FOREIGN KEY (`id_penduduk`) REFERENCES `tweb_penduduk` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `dtks_anggota_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: dtks_lampiran
#

DROP TABLE IF EXISTS `dtks_lampiran`;

CREATE TABLE `dtks_lampiran` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_rtm` int(11) DEFAULT NULL,
  `judul` varchar(30) NOT NULL,
  `keterangan` varchar(100) NOT NULL,
  `foto` text NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `FK_dtks_lampiran_rtm` (`id_rtm`),
  KEY `dtks_lampiran_config_fk` (`config_id`),
  CONSTRAINT `FK_dtks_lampiran_rtm` FOREIGN KEY (`id_rtm`) REFERENCES `tweb_rtm` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `dtks_lampiran_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: dtks_pengaturan_program
#

DROP TABLE IF EXISTS `dtks_pengaturan_program`;

CREATE TABLE `dtks_pengaturan_program` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `versi_kuisioner` int(11) NOT NULL,
  `kode` varchar(25) NOT NULL,
  `id_bantuan` int(11) DEFAULT NULL,
  `nilai_default` varchar(50) DEFAULT NULL,
  `target_table` varchar(100) NOT NULL,
  `target_field` text NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `config_idversi_kuisionerkode` (`config_id`,`versi_kuisioner`,`kode`),
  KEY `FK_dtks_p_program` (`id_bantuan`),
  CONSTRAINT `FK_dtks_p_program` FOREIGN KEY (`id_bantuan`) REFERENCES `program` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `dtks_pengaturan_program_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: dtks_ref_lampiran
#

DROP TABLE IF EXISTS `dtks_ref_lampiran`;

CREATE TABLE `dtks_ref_lampiran` (
  `id_dtks` int(11) NOT NULL,
  `id_lampiran` int(11) NOT NULL,
  KEY `FK_ref_lampiran_dtks` (`id_dtks`),
  KEY `FK_lampiran_dtks` (`id_lampiran`),
  CONSTRAINT `FK_lampiran_dtks` FOREIGN KEY (`id_lampiran`) REFERENCES `dtks_lampiran` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_ref_lampiran_dtks` FOREIGN KEY (`id_dtks`) REFERENCES `dtks` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: fcm_token
#

DROP TABLE IF EXISTS `fcm_token`;

CREATE TABLE `fcm_token` (
  `id_user` int(11) DEFAULT NULL,
  `config_id` int(11) DEFAULT NULL,
  `device` varchar(255) NOT NULL,
  `token` longtext NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  UNIQUE KEY `fcm_token_device_unique` (`device`),
  KEY `fcm_token_dd_user_fk` (`id_user`),
  KEY `fcm_token_config_fk` (`config_id`),
  CONSTRAINT `fcm_token_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fcm_token_dd_user_fk` FOREIGN KEY (`id_user`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: fcm_token_mandiri
#

DROP TABLE IF EXISTS `fcm_token_mandiri`;

CREATE TABLE `fcm_token_mandiri` (
  `id_user_mandiri` int(11) DEFAULT NULL,
  `config_id` int(11) DEFAULT NULL,
  `device` varchar(255) NOT NULL COMMENT 'id device dari android pemohon',
  `token` longtext NOT NULL COMMENT 'token yang didapat dari FCM',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  UNIQUE KEY `fcm_token_mandiri_device_unique` (`device`),
  KEY `fcm_token_mandiri_config_fk` (`config_id`),
  KEY `fcm_token_mandiri_user_mandiri_fk` (`id_user_mandiri`),
  CONSTRAINT `fcm_token_mandiri_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fcm_token_mandiri_user_mandiri_fk` FOREIGN KEY (`id_user_mandiri`) REFERENCES `tweb_penduduk_mandiri` (`id_pend`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: gambar_gallery
#

DROP TABLE IF EXISTS `gambar_gallery`;

CREATE TABLE `gambar_gallery` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `parrent` int(4) DEFAULT '0',
  `gambar` text,
  `nama` varchar(50) NOT NULL,
  `enabled` int(2) NOT NULL DEFAULT '1',
  `tgl_upload` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tipe` int(4) DEFAULT '0',
  `slider` tinyint(1) DEFAULT NULL,
  `urut` int(5) DEFAULT NULL,
  `jenis` tinyint(4) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `parrent` (`parrent`),
  KEY `gambar_gallery_config_fk` (`config_id`),
  CONSTRAINT `gambar_gallery_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: garis
#

DROP TABLE IF EXISTS `garis`;

CREATE TABLE `garis` (
  `id` int(4) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `nama` varchar(50) NOT NULL,
  `path` mediumtext,
  `enabled` int(11) NOT NULL DEFAULT '1',
  `ref_line` int(9) NOT NULL,
  `foto` varchar(100) DEFAULT NULL,
  `desk` mediumtext,
  `id_cluster` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `garis_config_fk` (`config_id`),
  KEY `garis_cluster_fk` (`id_cluster`),
  CONSTRAINT `garis_cluster_fk` FOREIGN KEY (`id_cluster`) REFERENCES `tweb_wil_clusterdesa` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `garis_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: gis_simbol
#

DROP TABLE IF EXISTS `gis_simbol`;

CREATE TABLE `gis_simbol` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `simbol` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `simbol_config` (`config_id`,`simbol`),
  CONSTRAINT `gis_simbol_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=796 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: grup_akses
#

DROP TABLE IF EXISTS `grup_akses`;

CREATE TABLE `grup_akses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_grup` int(11) NOT NULL,
  `id_modul` int(11) NOT NULL,
  `akses` tinyint(4) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_grup` (`id_grup`),
  KEY `id_modul` (`id_modul`),
  KEY `grup_akses_config_fk` (`config_id`),
  CONSTRAINT `fk_id_grup` FOREIGN KEY (`id_grup`) REFERENCES `user_grup` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_id_modul` FOREIGN KEY (`id_modul`) REFERENCES `setting_modul` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `grup_akses_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1023 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: hubung_warga
#

DROP TABLE IF EXISTS `hubung_warga`;

CREATE TABLE `hubung_warga` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_grup` int(11) NOT NULL,
  `subjek` varchar(100) NOT NULL,
  `isi` text NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int(11) NOT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `hubung_warga_config_fk` (`config_id`),
  CONSTRAINT `hubung_warga_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: ibu_hamil
#

DROP TABLE IF EXISTS `ibu_hamil`;

CREATE TABLE `ibu_hamil` (
  `id_ibu_hamil` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `posyandu_id` int(11) DEFAULT NULL,
  `kia_id` int(11) DEFAULT NULL,
  `status_kehamilan` tinyint(1) DEFAULT NULL,
  `usia_kehamilan` tinyint(255) DEFAULT NULL,
  `tanggal_melahirkan` date DEFAULT NULL,
  `pemeriksaan_kehamilan` tinyint(1) NOT NULL,
  `konsumsi_pil_fe` tinyint(1) NOT NULL,
  `butir_pil_fe` int(11) NOT NULL,
  `pemeriksaan_nifas` tinyint(1) NOT NULL,
  `konseling_gizi` tinyint(1) NOT NULL,
  `kunjungan_rumah` tinyint(1) NOT NULL,
  `akses_air_bersih` tinyint(1) NOT NULL,
  `kepemilikan_jamban` tinyint(1) NOT NULL,
  `jaminan_kesehatan` tinyint(1) NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id_ibu_hamil`),
  KEY `ibu_hamil_config_fk` (`config_id`),
  KEY `ibu_hamil_posyandu_fk` (`posyandu_id`),
  KEY `ibu_hamil_kia_fk` (`kia_id`),
  CONSTRAINT `ibu_hamil_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ibu_hamil_kia_fk` FOREIGN KEY (`kia_id`) REFERENCES `kia` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ibu_hamil_posyandu_fk` FOREIGN KEY (`posyandu_id`) REFERENCES `posyandu` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: inbox
#

DROP TABLE IF EXISTS `inbox`;

CREATE TABLE `inbox` (
  `UpdatedInDB` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `ReceivingDateTime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Text` text NOT NULL,
  `SenderNumber` varchar(20) NOT NULL DEFAULT '',
  `Coding` enum('Default_No_Compression','Unicode_No_Compression','8bit','Default_Compression','Unicode_Compression') NOT NULL DEFAULT 'Default_No_Compression',
  `UDH` text NOT NULL,
  `SMSCNumber` varchar(20) NOT NULL DEFAULT '',
  `Class` int(11) NOT NULL DEFAULT '-1',
  `TextDecoded` text NOT NULL,
  `ID` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `RecipientID` text NOT NULL,
  `Processed` enum('false','true') NOT NULL DEFAULT 'false',
  PRIMARY KEY (`ID`),
  KEY `inbox_config_fk` (`config_id`),
  CONSTRAINT `inbox_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: inventaris_asset
#

DROP TABLE IF EXISTS `inventaris_asset`;

CREATE TABLE `inventaris_asset` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `nama_barang` varchar(255) NOT NULL,
  `kode_barang` varchar(64) NOT NULL,
  `register` varchar(64) NOT NULL,
  `jenis` varchar(255) NOT NULL,
  `judul_buku` varchar(255) DEFAULT NULL,
  `spesifikasi_buku` varchar(255) DEFAULT NULL,
  `asal_daerah` varchar(255) DEFAULT NULL,
  `pencipta` varchar(255) DEFAULT NULL,
  `bahan` varchar(255) DEFAULT NULL,
  `jenis_hewan` varchar(255) DEFAULT NULL,
  `ukuran_hewan` varchar(255) DEFAULT NULL,
  `jenis_tumbuhan` varchar(255) DEFAULT NULL,
  `ukuran_tumbuhan` varchar(255) DEFAULT NULL,
  `jumlah` int(64) NOT NULL,
  `tahun_pengadaan` year(4) NOT NULL,
  `asal` varchar(255) NOT NULL,
  `harga` double NOT NULL,
  `keterangan` mediumtext NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int(11) NOT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int(11) NOT NULL,
  `status` int(1) NOT NULL DEFAULT '0',
  `visible` int(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `inventaris_asset_config_fk` (`config_id`),
  CONSTRAINT `inventaris_asset_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: inventaris_gedung
#

DROP TABLE IF EXISTS `inventaris_gedung`;

CREATE TABLE `inventaris_gedung` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `nama_barang` varchar(255) NOT NULL,
  `kode_barang` varchar(64) NOT NULL,
  `register` varchar(64) NOT NULL,
  `kondisi_bangunan` varchar(255) NOT NULL,
  `kontruksi_bertingkat` varchar(255) DEFAULT NULL,
  `kontruksi_beton` tinyint(1) DEFAULT '0',
