DROP TABLE IF EXISTS `keuangan_ta_spppot`;

CREATE TABLE `keuangan_ta_spppot` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_keuangan_master` int(11) NOT NULL,
  `Tahun` varchar(100) NOT NULL,
  `Kd_Desa` varchar(100) NOT NULL,
  `No_SPP` varchar(100) NOT NULL,
  `Kd_Keg` varchar(100) NOT NULL,
  `No_Bukti` varchar(100) NOT NULL,
  `Kd_Rincian` varchar(100) NOT NULL,
  `Nilai` varchar(100) NOT NULL,
  `Billing_Pajak` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_keuangan_ta_spppot_master_fk` (`id_keuangan_master`),
  KEY `keuangan_ta_spppot_config_fk` (`config_id`),
  CONSTRAINT `id_keuangan_ta_spppot_master_fk` FOREIGN KEY (`id_keuangan_master`) REFERENCES `keuangan_master` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `keuangan_ta_spppot_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=170 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: keuangan_ta_sts
#

DROP TABLE IF EXISTS `keuangan_ta_sts`;

CREATE TABLE `keuangan_ta_sts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_keuangan_master` int(11) NOT NULL,
  `Tahun` varchar(100) NOT NULL,
  `No_Bukti` varchar(100) NOT NULL,
  `Tgl_Bukti` varchar(100) NOT NULL,
  `Kd_Desa` varchar(100) NOT NULL,
  `Uraian` varchar(100) NOT NULL,
  `NoRek_Bank` varchar(100) NOT NULL,
  `Nama_Bank` varchar(100) NOT NULL,
  `Jumlah` varchar(100) NOT NULL,
  `Nm_Bendahara` varchar(100) NOT NULL,
  `Jbt_Bendahara` varchar(100) NOT NULL,
  `ID_Bank` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_keuangan_ta_sts_master_fk` (`id_keuangan_master`),
  KEY `keuangan_ta_sts_config_fk` (`config_id`),
  CONSTRAINT `id_keuangan_ta_sts_master_fk` FOREIGN KEY (`id_keuangan_master`) REFERENCES `keuangan_master` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `keuangan_ta_sts_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: keuangan_ta_sts_rinci
#

DROP TABLE IF EXISTS `keuangan_ta_sts_rinci`;

CREATE TABLE `keuangan_ta_sts_rinci` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_keuangan_master` int(11) NOT NULL,
  `Tahun` varchar(100) NOT NULL,
  `Kd_Desa` varchar(100) NOT NULL,
  `No_Bukti` varchar(100) NOT NULL,
  `No_TBP` varchar(100) NOT NULL,
  `Uraian` varchar(100) NOT NULL,
  `Nilai` varchar(100) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `id_keuangan_ta_sts_rinci_master_fk` (`id_keuangan_master`),
  KEY `keuangan_ta_sts_rinci_config_fk` (`config_id`),
  CONSTRAINT `id_keuangan_ta_sts_rinci_master_fk` FOREIGN KEY (`id_keuangan_master`) REFERENCES `keuangan_master` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `keuangan_ta_sts_rinci_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: keuangan_ta_tbp
#

DROP TABLE IF EXISTS `keuangan_ta_tbp`;

CREATE TABLE `keuangan_ta_tbp` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_keuangan_master` int(11) NOT NULL,
  `Tahun` varchar(100) NOT NULL,
  `No_Bukti` varchar(100) NOT NULL,
  `Tgl_Bukti` varchar(100) NOT NULL,
  `Kd_Desa` varchar(100) NOT NULL,
  `Uraian` varchar(250) DEFAULT NULL,
  `Nm_Penyetor` varchar(100) NOT NULL,
  `Alamat_Penyetor` varchar(100) NOT NULL,
  `TTD_Penyetor` varchar(100) NOT NULL,
  `NoRek_Bank` varchar(100) NOT NULL,
  `Nama_Bank` varchar(100) NOT NULL,
  `Jumlah` varchar(100) NOT NULL,
  `Nm_Bendahara` varchar(100) NOT NULL,
  `Jbt_Bendahara` varchar(100) NOT NULL,
  `Status` varchar(100) NOT NULL,
  `KdBayar` varchar(100) NOT NULL,
  `Ref_Bayar` varchar(100) NOT NULL,
  `ID_Bank` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_keuangan_ta_tbp_master_fk` (`id_keuangan_master`),
  KEY `keuangan_ta_tbp_config_fk` (`config_id`),
  CONSTRAINT `id_keuangan_ta_tbp_master_fk` FOREIGN KEY (`id_keuangan_master`) REFERENCES `keuangan_master` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `keuangan_ta_tbp_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: keuangan_ta_tbp_rinci
#

DROP TABLE IF EXISTS `keuangan_ta_tbp_rinci`;

CREATE TABLE `keuangan_ta_tbp_rinci` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_keuangan_master` int(11) NOT NULL,
  `Tahun` varchar(100) NOT NULL,
  `No_Bukti` varchar(100) NOT NULL,
  `Kd_Desa` varchar(100) NOT NULL,
  `Kd_Keg` varchar(100) NOT NULL,
  `Kd_Rincian` varchar(100) NOT NULL,
  `RincianSD` varchar(100) NOT NULL,
  `SumberDana` varchar(100) NOT NULL,
  `nilai` varchar(100) NOT NULL,
  `Kd_SubRinci` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_keuangan_ta_tbp_rinci_master_fk` (`id_keuangan_master`),
  KEY `keuangan_ta_tbp_rinci_config_fk` (`config_id`),
  CONSTRAINT `id_keuangan_ta_tbp_rinci_master_fk` FOREIGN KEY (`id_keuangan_master`) REFERENCES `keuangan_master` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `keuangan_ta_tbp_rinci_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: keuangan_ta_triwulan
#

DROP TABLE IF EXISTS `keuangan_ta_triwulan`;

CREATE TABLE `keuangan_ta_triwulan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_keuangan_master` int(11) NOT NULL,
  `KURincianSD` varchar(100) NOT NULL,
  `Tahun` varchar(100) NOT NULL,
  `Sifat` varchar(100) NOT NULL,
  `SumberDana` varchar(100) NOT NULL,
  `Kd_Desa` varchar(100) NOT NULL,
  `Kd_Keg` varchar(100) NOT NULL,
  `Kd_Rincian` varchar(100) NOT NULL,
  `Anggaran` varchar(100) NOT NULL,
  `AnggaranPAK` varchar(100) NOT NULL,
  `Tw1Rinci` varchar(100) DEFAULT NULL,
  `Tw2Rinci` varchar(100) DEFAULT NULL,
  `Tw3Rinci` varchar(100) DEFAULT NULL,
  `Tw4Rinci` varchar(100) DEFAULT NULL,
  `KunciData` varchar(100) NOT NULL,
  `Jan` varchar(100) DEFAULT NULL,
  `Peb` varchar(100) DEFAULT NULL,
  `Mar` varchar(100) DEFAULT NULL,
  `Apr` varchar(100) DEFAULT NULL,
  `Mei` varchar(100) DEFAULT NULL,
  `Jun` varchar(100) DEFAULT NULL,
  `Jul` varchar(100) DEFAULT NULL,
  `Agt` varchar(100) DEFAULT NULL,
  `Sep` varchar(100) DEFAULT NULL,
  `Okt` varchar(100) DEFAULT NULL,
  `Nop` varchar(100) DEFAULT NULL,
  `Des` varchar(100) DEFAULT NULL,
  `Kd_SubRinci` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_keuangan_ta_triwulan_master_fk` (`id_keuangan_master`),
  KEY `keuangan_ta_triwulan_config_fk` (`config_id`),
  CONSTRAINT `id_keuangan_ta_triwulan_master_fk` FOREIGN KEY (`id_keuangan_master`) REFERENCES `keuangan_master` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `keuangan_ta_triwulan_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: keuangan_ta_triwulan_rinci
#

DROP TABLE IF EXISTS `keuangan_ta_triwulan_rinci`;

CREATE TABLE `keuangan_ta_triwulan_rinci` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_keuangan_master` int(11) NOT NULL,
  `KdPosting` varchar(100) NOT NULL,
  `KURincianSD` varchar(100) NOT NULL,
  `Tahun` varchar(100) NOT NULL,
  `Sifat` varchar(100) NOT NULL,
  `SumberDana` varchar(100) NOT NULL,
  `Kd_Desa` varchar(100) NOT NULL,
  `Kd_Keg` varchar(100) NOT NULL,
  `Kd_Rincian` varchar(100) NOT NULL,
  `Anggaran` varchar(100) NOT NULL,
  `AnggaranPAK` varchar(100) NOT NULL,
  `Tw1Rinci` varchar(100) DEFAULT NULL,
  `Tw2Rinci` varchar(100) DEFAULT NULL,
  `Tw3Rinci` varchar(100) DEFAULT NULL,
  `Tw4Rinci` varchar(100) DEFAULT NULL,
  `KunciData` varchar(100) NOT NULL,
  `Jan` varchar(100) DEFAULT NULL,
  `Peb` varchar(100) DEFAULT NULL,
  `Mar` varchar(100) DEFAULT NULL,
  `Apr` varchar(100) DEFAULT NULL,
  `Mei` varchar(100) DEFAULT NULL,
  `Jun` varchar(100) DEFAULT NULL,
  `Jul` varchar(100) DEFAULT NULL,
  `Agt` varchar(100) DEFAULT NULL,
  `Sep` varchar(100) DEFAULT NULL,
  `Okt` varchar(100) DEFAULT NULL,
  `Nop` varchar(100) DEFAULT NULL,
  `Des` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_keuangan_ta_triwulan_rinci_master_fk` (`id_keuangan_master`),
  KEY `keuangan_ta_triwulan_rinci_config_fk` (`config_id`),
  CONSTRAINT `id_keuangan_ta_triwulan_rinci_master_fk` FOREIGN KEY (`id_keuangan_master`) REFERENCES `keuangan_master` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `keuangan_ta_triwulan_rinci_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: kia
#

DROP TABLE IF EXISTS `kia`;

CREATE TABLE `kia` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `no_kia` varchar(255) NOT NULL,
  `ibu_id` int(11) DEFAULT NULL,
  `anak_id` int(11) DEFAULT NULL,
  `hari_perkiraan_lahir` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `no_kia` (`no_kia`),
  KEY `kia_config_fk` (`config_id`),
  KEY `kia_ibu_fk` (`ibu_id`),
  KEY `kia_anak_fk` (`anak_id`),
  CONSTRAINT `kia_anak_fk` FOREIGN KEY (`anak_id`) REFERENCES `tweb_penduduk` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `kia_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `kia_ibu_fk` FOREIGN KEY (`ibu_id`) REFERENCES `tweb_penduduk` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: klasifikasi_surat
#

DROP TABLE IF EXISTS `klasifikasi_surat`;

CREATE TABLE `klasifikasi_surat` (
  `id` int(4) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `kode` varchar(50) NOT NULL,
  `nama` text NOT NULL,
  `uraian` longtext NOT NULL,
  `enabled` int(2) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `config_idkode` (`config_id`,`kode`),
  CONSTRAINT `klasifikasi_surat_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2335 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: komentar
#

DROP TABLE IF EXISTS `komentar`;

CREATE TABLE `komentar` (
  `id` int(5) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_artikel` int(11) DEFAULT NULL,
  `owner` varchar(50) NOT NULL,
  `email` varchar(50) DEFAULT NULL,
  `subjek` tinytext,
  `komentar` text NOT NULL,
  `tgl_upload` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` tinyint(1) DEFAULT NULL,
  `tipe` tinyint(1) DEFAULT NULL,
  `no_hp` varchar(15) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_archived` tinyint(1) DEFAULT '0',
  `permohonan` text,
  `parent_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `komentar_config_fk` (`config_id`),
  KEY `komentar_artikel_fk` (`id_artikel`),
  CONSTRAINT `komentar_artikel_fk` FOREIGN KEY (`id_artikel`) REFERENCES `artikel` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `komentar_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: kontak
#

DROP TABLE IF EXISTS `kontak`;

CREATE TABLE `kontak` (
  `id_kontak` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `nama` varchar(100) NOT NULL,
  `telepon` varchar(20) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `telegram` varchar(50) DEFAULT NULL,
  `hubung_warga` varchar(50) NOT NULL DEFAULT 'Telegram',
  `keterangan` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_kontak`),
  UNIQUE KEY `telepon_config` (`config_id`,`telepon`),
  UNIQUE KEY `email_config` (`config_id`,`email`),
  UNIQUE KEY `telegram_config` (`config_id`,`telegram`),
  CONSTRAINT `kontak_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: kontak_grup
#

DROP TABLE IF EXISTS `kontak_grup`;

CREATE TABLE `kontak_grup` (
  `id_grup` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `nama_grup` varchar(30) NOT NULL,
  `keterangan` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_grup`),
  KEY `kontak_grup_config_fk` (`config_id`),
  CONSTRAINT `kontak_grup_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: laporan_sinkronisasi
#

DROP TABLE IF EXISTS `laporan_sinkronisasi`;

CREATE TABLE `laporan_sinkronisasi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `tipe` varchar(50) DEFAULT NULL,
  `judul` varchar(100) NOT NULL,
  `tahun` int(11) NOT NULL,
  `semester` int(11) NOT NULL,
  `nama_file` varchar(100) NOT NULL,
  `kirim` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `laporan_sinkronisasi_config_fk` (`config_id`),
  CONSTRAINT `laporan_sinkronisasi_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: line
#

DROP TABLE IF EXISTS `line`;

CREATE TABLE `line` (
  `id` int(4) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `nama` varchar(50) NOT NULL,
  `simbol` varchar(50) DEFAULT NULL,
  `color` varchar(25) DEFAULT NULL,
  `tipe` int(4) DEFAULT '0',
  `tebal` int(2) DEFAULT '3',
  `jenis` varchar(10) DEFAULT 'solid',
  `parrent` int(4) DEFAULT '1',
  `enabled` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `parrent` (`parrent`),
  KEY `line_config_fk` (`config_id`),
  CONSTRAINT `line_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: log_backup
#

DROP TABLE IF EXISTS `log_backup`;

CREATE TABLE `log_backup` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `ukuran` varchar(50) DEFAULT NULL,
  `path` varchar(150) DEFAULT NULL,
  `permanen` tinyint(1) NOT NULL DEFAULT '0',
  `downloaded_at` timestamp NULL DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '0',
  `pid_process` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `log_backup_config_fk` (`config_id`),
  CONSTRAINT `log_backup_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: log_ekspor
#

DROP TABLE IF EXISTS `log_ekspor`;

CREATE TABLE `log_ekspor` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tgl_ekspor` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `kode_ekspor` varchar(100) NOT NULL,
  `semua` int(1) NOT NULL DEFAULT '1',
  `dari_tgl` date DEFAULT NULL,
  `total` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: log_hapus_penduduk
#

DROP TABLE IF EXISTS `log_hapus_penduduk`;

CREATE TABLE `log_hapus_penduduk` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_pend` int(11) DEFAULT NULL,
  `nik` decimal(16,0) NOT NULL,
  `foto` varchar(100) DEFAULT NULL,
  `deleted_by` varchar(100) DEFAULT NULL,
  `deleted_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `log_hapus_penduduk_config_fk` (`config_id`),
  KEY `log_hapus_penduduk_pend_fk` (`id_pend`),
  CONSTRAINT `log_hapus_penduduk_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_hapus_penduduk_pend_fk` FOREIGN KEY (`id_pend`) REFERENCES `tweb_penduduk` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: log_keluarga
#

DROP TABLE IF EXISTS `log_keluarga`;

CREATE TABLE `log_keluarga` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_kk` int(11) DEFAULT NULL,
  `id_peristiwa` int(4) NOT NULL,
  `tgl_peristiwa` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_pend` int(11) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `id_log_penduduk` int(10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_kk_config` (`config_id`,`id_kk`,`id_peristiwa`,`tgl_peristiwa`,`id_pend`),
  KEY `log_penduduk_fk` (`id_log_penduduk`),
  KEY `log_keluarga_pend_fk` (`id_pend`),
  KEY `log_keluarga_kk_fk` (`id_kk`),
  CONSTRAINT `log_keluarga_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_keluarga_kk_fk` FOREIGN KEY (`id_kk`) REFERENCES `tweb_keluarga` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_keluarga_pend_fk` FOREIGN KEY (`id_pend`) REFERENCES `tweb_penduduk` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_penduduk_fk` FOREIGN KEY (`id_log_penduduk`) REFERENCES `log_penduduk` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: log_login
#

DROP TABLE IF EXISTS `log_login`;

CREATE TABLE `log_login` (
  `uuid` char(36) NOT NULL,
  `config_id` int(11) NOT NULL,
  `username` varchar(255) NOT NULL,
  `ip_address` varchar(255) NOT NULL,
  `user_agent` varchar(255) NOT NULL,
  `referer` varchar(255) NOT NULL,
  `lainnya` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`uuid`),
  UNIQUE KEY `log_login_uuid_config_id_unique` (`uuid`,`config_id`),
  KEY `log_login_config_id_foreign` (`config_id`),
  CONSTRAINT `log_login_config_id_foreign` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: log_notifikasi_admin
#

DROP TABLE IF EXISTS `log_notifikasi_admin`;

CREATE TABLE `log_notifikasi_admin` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `id_user` int(11) DEFAULT NULL,
  `config_id` int(11) DEFAULT NULL,
  `judul` varchar(255) NOT NULL,
  `isi` text NOT NULL,
  `image` varchar(255) DEFAULT NULL,
  `payload` varchar(255) NOT NULL,
  `read` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `log_notifikasi_admin_id_created_at_read_device_config_id_index` (`id`,`created_at`,`read`,`config_id`),
  KEY `log_notifikasi_admin_config_fk` (`config_id`),
  KEY `log_notifikasi_admin_user_fk` (`id_user`),
  CONSTRAINT `log_notifikasi_admin_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_notifikasi_admin_user_fk` FOREIGN KEY (`id_user`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: log_notifikasi_mandiri
#

DROP TABLE IF EXISTS `log_notifikasi_mandiri`;

CREATE TABLE `log_notifikasi_mandiri` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_user_mandiri` int(11) DEFAULT NULL,
  `config_id` int(11) DEFAULT NULL,
  `judul` varchar(255) NOT NULL COMMENT 'Judul notifikasi',
  `isi` text NOT NULL COMMENT 'Isi notifikasi',
  `image` varchar(255) DEFAULT NULL COMMENT 'gambar notifikasi, jika ada',
  `payload` varchar(100) NOT NULL COMMENT 'Tujuan navicasi saat notifikasi di klik',
  `read` tinyint(4) NOT NULL COMMENT 'menandatakan notifikasi sudah terbaca atau belum, 1 artinya sudah dibaca, 0 artinya belum dibaca',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `log_notifikasi_mandiri_id_created_at_read_device_config_id_index` (`id`,`created_at`,`read`,`config_id`),
  KEY `log_notifikasi_mandiri_config_fk` (`config_id`),
  KEY `log_notifikasi_mandiri_user_mandiri_fk` (`id_user_mandiri`),
  CONSTRAINT `log_notifikasi_mandiri_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_notifikasi_mandiri_user_mandiri_fk` FOREIGN KEY (`id_user_mandiri`) REFERENCES `tweb_penduduk_mandiri` (`id_pend`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: log_penduduk
#

DROP TABLE IF EXISTS `log_penduduk`;

CREATE TABLE `log_penduduk` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_pend` int(11) NOT NULL,
  `kode_peristiwa` int(11) DEFAULT NULL,
  `meninggal_di` varchar(50) DEFAULT NULL,
  `jam_mati` varchar(10) DEFAULT NULL,
  `sebab` varchar(50) DEFAULT NULL,
  `penolong_mati` varchar(50) DEFAULT NULL,
  `akta_mati` varchar(50) DEFAULT NULL,
  `file_akta_mati` varchar(255) DEFAULT NULL,
  `alamat_tujuan` tinytext,
  `tgl_lapor` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tgl_peristiwa` datetime DEFAULT CURRENT_TIMESTAMP,
  `catatan` text,
  `no_kk` varchar(16) DEFAULT NULL,
  `nama_kk` varchar(100) DEFAULT NULL,
  `ref_pindah` tinyint(4) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  `maksud_tujuan_kedatangan` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_pend_config` (`config_id`,`id_pend`,`kode_peristiwa`,`tgl_peristiwa`),
  KEY `id_ref_pindah` (`ref_pindah`),
  KEY `config_id` (`config_id`),
  KEY `id_pend` (`id_pend`),
  KEY `kode_peristiwa` (`kode_peristiwa`),
  KEY `tgl_peristiwa` (`tgl_peristiwa`),
  CONSTRAINT `fk_tweb_penduduk` FOREIGN KEY (`id_pend`) REFERENCES `tweb_penduduk` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `id_ref_pindah` FOREIGN KEY (`ref_pindah`) REFERENCES `ref_pindah` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_penduduk_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=103 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: log_perubahan_penduduk
#

DROP TABLE IF EXISTS `log_perubahan_penduduk`;

CREATE TABLE `log_perubahan_penduduk` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_pend` int(11) DEFAULT NULL,
  `id_cluster` int(11) DEFAULT NULL,
  `tanggal` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `log_perubahan_penduduk_config_fk` (`config_id`),
  KEY `log_perubahan_penduduk_pend_fk` (`id_pend`),
  KEY `log_perubahan_penduduk_cluster_fk` (`id_cluster`),
  CONSTRAINT `log_perubahan_penduduk_cluster_fk` FOREIGN KEY (`id_cluster`) REFERENCES `tweb_wil_clusterdesa` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_perubahan_penduduk_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_perubahan_penduduk_pend_fk` FOREIGN KEY (`id_pend`) REFERENCES `tweb_penduduk` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: log_restore_desa
#

DROP TABLE IF EXISTS `log_restore_desa`;

CREATE TABLE `log_restore_desa` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `ukuran` varchar(50) DEFAULT NULL,
  `path` varchar(150) DEFAULT NULL,
  `restore_at` timestamp NULL DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '0',
  `pid_process` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `log_restore_desa_config_fk` (`config_id`),
  CONSTRAINT `log_restore_desa_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: log_sinkronisasi
#

DROP TABLE IF EXISTS `log_sinkronisasi`;

CREATE TABLE `log_sinkronisasi` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `modul` varchar(50) NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `modul_config` (`config_id`,`modul`),
  CONSTRAINT `log_sinkronisasi_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: log_surat
#

DROP TABLE IF EXISTS `log_surat`;

CREATE TABLE `log_surat` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_format_surat` int(11) DEFAULT NULL,
  `id_pend` int(11) DEFAULT NULL,
  `id_pamong` int(11) DEFAULT NULL,
  `nama_pamong` varchar(100) DEFAULT NULL COMMENT 'Nama pamong agar tidak berubah saat ada perubahan di master pamong',
  `nama_jabatan` varchar(100) DEFAULT NULL,
  `id_user` int(11) DEFAULT NULL,
  `tanggal` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `bulan` varchar(2) DEFAULT NULL,
  `tahun` varchar(4) DEFAULT NULL,
  `no_surat` varchar(20) DEFAULT NULL,
  `nama_surat` varchar(100) DEFAULT NULL,
  `lampiran` varchar(100) DEFAULT NULL,
  `nik_non_warga` decimal(16,0) DEFAULT NULL,
  `nama_non_warga` varchar(100) DEFAULT NULL,
  `keterangan` varchar(200) DEFAULT NULL,
  `lokasi_arsip` varchar(150) DEFAULT '',
  `urls_id` int(11) DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0. Konsep, 1. Cetak',
  `log_verifikasi` varchar(100) DEFAULT NULL,
  `tte` tinyint(1) DEFAULT NULL,
  `verifikasi_operator` tinyint(1) DEFAULT NULL,
  `verifikasi_kades` tinyint(1) DEFAULT NULL,
  `verifikasi_sekdes` tinyint(1) DEFAULT NULL,
  `isi_surat` longtext,
  `kecamatan` tinyint(1) NOT NULL DEFAULT '1',
  `deleted_at` datetime DEFAULT NULL,
  `pemohon` varchar(200) DEFAULT NULL,
  `input` longtext,
  PRIMARY KEY (`id`),
  UNIQUE KEY `urls_id` (`urls_id`),
  KEY `log_surat_config_fk` (`config_id`),
  KEY `log_surat_format_surat_fk` (`id_format_surat`),
  KEY `log_surat_pend_fk` (`id_pend`),
  KEY `log_surat_pamong_fk` (`id_pamong`),
  KEY `log_surat_user_fk` (`id_user`),
  CONSTRAINT `log_surat_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_surat_format_surat_fk` FOREIGN KEY (`id_format_surat`) REFERENCES `tweb_surat_format` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_surat_pamong_fk` FOREIGN KEY (`id_pamong`) REFERENCES `tweb_desa_pamong` (`pamong_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_surat_pamong_urls_fk` FOREIGN KEY (`urls_id`) REFERENCES `urls` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_surat_pend_fk` FOREIGN KEY (`id_pend`) REFERENCES `tweb_penduduk` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_surat_user_fk` FOREIGN KEY (`id_user`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: log_surat_dinas
#

DROP TABLE IF EXISTS `log_surat_dinas`;

CREATE TABLE `log_surat_dinas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_format_surat` int(11) NOT NULL,
  `id_pamong` int(11) NOT NULL,
  `nama_pamong` varchar(100) DEFAULT NULL COMMENT 'Nama pamong agar tidak berubah saat ada perubahan di master pamong',
  `nama_jabatan` varchar(100) DEFAULT NULL,
  `id_user` int(11) NOT NULL,
  `tanggal` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `bulan` varchar(2) DEFAULT NULL,
  `tahun` varchar(4) DEFAULT NULL,
  `no_surat` varchar(20) DEFAULT NULL,
  `nama_surat` varchar(100) DEFAULT NULL,
  `lampiran` varchar(100) DEFAULT NULL,
  `keterangan` varchar(200) DEFAULT NULL,
  `lokasi_arsip` varchar(150) DEFAULT '',
  `urls_id` int(11) DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0. Konsep, 1. Cetak',
  `log_verifikasi` varchar(100) DEFAULT NULL,
  `tte` tinyint(1) DEFAULT NULL,
  `verifikasi_operator` tinyint(1) DEFAULT NULL,
  `verifikasi_kades` tinyint(1) DEFAULT NULL,
  `verifikasi_sekdes` tinyint(1) DEFAULT NULL,
  `isi_surat` longtext,
  `input` longtext,
  `karakter` tinyint(4) DEFAULT '1' COMMENT '1:biasa, 2:terbatas, 3:rahasia',
  `derajat` tinyint(4) DEFAULT '1' COMMENT '1:biasa, 2:segera, 3:sangat segera',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `urls_id` (`urls_id`),
  KEY `log_surat_dinas_format_fk` (`id_format_surat`),
  KEY `log_surat_dinas_user_fk` (`id_user`),
  KEY `log_surat_dinas_created_by_fk` (`created_by`),
  KEY `log_surat_dinas_updated_by_fk` (`updated_by`),
  KEY `log_surat_config_fk` (`config_id`),
  CONSTRAINT `log_surat_dinas_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_surat_dinas_created_by_fk` FOREIGN KEY (`created_by`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_surat_dinas_format_fk` FOREIGN KEY (`id_format_surat`) REFERENCES `surat_dinas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_surat_dinas_updated_by_fk` FOREIGN KEY (`updated_by`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_surat_dinas_user_fk` FOREIGN KEY (`id_user`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: log_tolak
#

DROP TABLE IF EXISTS `log_tolak`;

CREATE TABLE `log_tolak` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `id_surat` int(11) DEFAULT NULL,
  `keterangan` longtext NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  `id_surat_dinas` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `log_tolak_config_fk` (`config_id`),
  KEY `log_tolak_surat_fk` (`id_surat`),
  KEY `log_tolak_surat_dinas_fk` (`id_surat_dinas`),
  CONSTRAINT `log_tolak_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_tolak_surat_dinas_fk` FOREIGN KEY (`id_surat_dinas`) REFERENCES `log_surat_dinas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `log_tolak_surat_fk` FOREIGN KEY (`id_surat`) REFERENCES `log_surat` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: log_tte
#

DROP TABLE IF EXISTS `log_tte`;

CREATE TABLE `log_tte` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `message` text,
  `jenis_error` varchar(150) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `log_tte_config_fk` (`config_id`),
  CONSTRAINT `log_tte_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: login_attempts
#

DROP TABLE IF EXISTS `login_attempts`;

CREATE TABLE `login_attempts` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `username` varchar(100) NOT NULL,
  `ip_address` varchar(45) NOT NULL,
  `time` int(11) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `login_attempts_config_fk` (`config_id`),
  CONSTRAINT `login_attempts_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8;



#
# TABLE STRUCTURE FOR: lokasi
#

DROP TABLE IF EXISTS `lokasi`;

CREATE TABLE `lokasi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `desk` mediumtext NOT NULL,
  `nama` varchar(50) NOT NULL,
  `enabled` int(11) NOT NULL DEFAULT '1',
