  KEY `persil_config_fk` (`config_id`),
  KEY `persil_wilayah_fk` (`id_wilayah`),
  KEY `persil_peta_fk` (`id_peta`),
  CONSTRAINT `persil_config_fk` FOREIGN KEY (`config_id`) REFERENCES `config` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `persil_peta_fk` FOREIGN KEY (`id_peta`) REFERENCES `lokasi` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `persil_wilayah_fk` FOREIGN KEY (`id_wilayah`) REFERENCES `tweb_wil_clusterdesa` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

