  CONSTRAINT `tanah_desa_penduduk_fk` FOREIGN KEY (`id_penduduk`) REFERENCES `tweb_penduduk` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

#
# TABLE STRUCTURE FOR: tanah_kas_desa
