INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (85, 1, '1471927406download (1).jpg', '<div class=\"contentText\">\r\n<div align=\"justify\">Bagian ini berisi informasi mengenai PemerintahanDesa. Sila klik pada tautan berikut untuk mendapatkan informasi yang lebih rinci.</div>\r\n<div align=\"justify\">&nbsp;</div>\r\n<ol>\r\n<li>Visi dan Misi</li>\r\n<li>Pemerintah Desa</li>\r\n<li>Badan Permusyawaratan Desa</li>\r\n</ol>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>VISI dan MISI</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>VISI</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>\"Senggigi Berseri\"</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>(Bersih, Relegius, Sejahtera, Rapi, dan Indah)</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>\"Terwujudnya masyarakat Desa Senggigi yang Bersih, Relegius, Sejahtra, Rapi dan Indah melalui Akselerasi Pembangunan yang berbasis Keagamaan, Budaya Hukum dan Berwawasan Lingkungan dengan berorentasi pada peningkatan Kinerja Aparatur dan Pemberdayaan Masyarakat\"</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>MISI</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Misi dan Program Desa Senggigi</strong></p>\r\n<p style=\"text-align: justify;\">Dan untuk melaksanakan visi Desa Senggigi dilaksanakan misi dan program sebagai berikut:</p>\r\n<p style=\"text-align: justify;\">1. Pembangunan Jangka Panjang</p>\r\n<ul>\r\n<li style=\"text-align: justify;\">Melanjutkan Pembangunan Desa yang belum terlaksana</li>\r\n<li style=\"text-align: justify;\">Meningkatkan Kerjasama antara pemerintah Desa dengan Lembaga desa yang ada</li>\r\n<li style=\"text-align: justify;\">Meningkatkan Kesejahtraan Masyarakat desa dengan meningkatkan sarana dan prasarana ekonomi warga.&nbsp;</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">2. Pembangunan Jangka Pendek &nbsp;</p>\r\n<ul>\r\n<li style=\"text-align: justify;\">Mengembangkan dan Menjaga serta melestarikan ada istiadat desa terutama yang telah mengakar di desa senggigi.&nbsp;</li>\r\n<li style=\"text-align: justify;\">Meningkatkan pelayanan dalam bidang pemerintahan kepada warga masyarakat&nbsp;</li>\r\n<li style=\"text-align: justify;\">Meningkatkan sarana dan prasarana ekonomi warga desa dengan perbaikan prasarana dan sarana ekonomi.</li>\r\n<li style=\"text-align: justify;\">Meningkatkan sarana dan prasarana pendidikan guna peningkatan sumber daya manusia desa senggigi.&nbsp;</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>Kepala Desa Senggigi</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>Muhammad Ilham</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</div>', 1, '2014-11-07 10:53:54', NULL, 1, 'Pemerintahan Desa', 0, '', '', '', '', '', 1, 'pemerintahan-desa', 25, 1, NULL, 3, 0, 'statis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (90, 1, '1471968200IMG-20160823-WA0007.jpg', '', 1, '2016-08-24 00:03:21', 5, 1, 'PERDES PHBS ', 0, '1471968200IMG-20160823-WA0012.jpg', '1471968200', '1471968200', 'PERDES PHBS.docx', 'PERDES PHBS ', 1, 'perdes-phbs', 14, 1, NULL, 3, 0, 'dinamis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (92, 1, '1472006396', '<p><strong>Susunan Organisasi Pemerintah Desa Senggigi</strong><br /><br />Kepala Desa: MUHAMMAD ILHAM<br />Sekretaris Desa:&nbsp;<span>MUSTAHIQ, S.Adm</span><br />Kepala Urusan Pemerintahan: SYAFRUDIN<br />Kepala Urusan&nbsp;Pembangunan: SYAFI\'I, SE<br />Kepala Urusan&nbsp;Kesra: HAMIDIAH<br />Kepala Urusan&nbsp;Keuangan: MARDIANA<br />Kepala Urusan&nbsp;Trantib: SUPARDI RUSTAM<br />Kepala Urusan&nbsp;Umum: MAHRUP<br /><br /></p>', 1, '2016-08-24 10:39:56', NULL, 1, 'Pemerintah Desa', 0, '1472006396', '1472006396', '1472006396', '', '', 1, 'pemerintah-desa', 33, 1, NULL, 3, 0, 'statis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (93, 1, '1549419057_visi-850x442.jpg', '<p style=\"text-align: center;\"><strong>VISI dan MISI</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>VISI</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>\"Senggigi Berseri\"</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>(Bersih, Relegius, Sejahtera, Rapi, dan Indah)</strong></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><strong>\"Terwujudnya masyarakat Desa Senggigi yang Bersih, Relegius, Sejahtera, Rapi dan Indah melalui Akselerasi Pembangunan yang berbasis Keagamaan, Budaya Hukum dan Berwawasan Lingkungan dengan berorentasi pada peningkatan Kinerja Aparatur dan Pemberdayaan Masyarakat\"</strong></p>\r\n<p>&nbsp;&nbsp;</p>\r\n<p><strong>MISI</strong></p>\r\n<p><strong>Misi dan Program Desa Senggigi</strong></p>\r\n<p>Dan untuk melaksanakan visi Desa Senggigi dilaksanakan misi dan program sebagai berikut:</p>\r\n<p>1. Pembangunan Jangka Panjang</p>\r\n<p>&nbsp; &nbsp; - Melanjutkan pembangunan desa yang belum terlaksana.</p>\r\n<p>&nbsp; &nbsp; - Meningkatkan kerjasama antara pemerintah desa dengan lembaga desa yang ada.</p>\r\n<p>&nbsp; &nbsp; - Meningkatkan kesejahtraan masyarakat desa dengan meningkatkan sarana dan prasarana ekonomi warga.&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>2. Pembangunan Jangka Pendek &nbsp;</p>\r\n<p>&nbsp; &nbsp; - Mengembangkan dan Menjaga serta melestarikan ada istiadat desa terutama yang telah mengakar di desa senggigi.&nbsp;</p>\r\n<p>&nbsp; &nbsp; - Meningkatkan pelayanan dalam bidang pemerintahan kepada warga masyarakat&nbsp;</p>\r\n<p>&nbsp; &nbsp; - Meningkatkan sarana dan prasarana ekonomi warga desa dengan perbaikan prasarana dan sarana ekonomi.</p>\r\n<p>&nbsp; &nbsp; - Meningkatkan sarana dan prasarana pendidikan guna peningkatan sumber daya manusia Desa Senggigi.&nbsp;</p>', 1, '2016-08-24 10:48:28', NULL, 1, 'Visi dan Misi', 0, '1472006908', '1472006908', '1472006908', '', '', 1, 'visi-dan-misi', 36, 1, NULL, 3, 0, 'statis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (94, 1, '1527544437_gotong-royong-pantai.jpeg', '<p style=\"text-align: justify;\">Gotong royong yang dulu digagas pertama kali oleh pendiri bangsa, Ir. Soekarno kian hari semakin terkikis dengan budaya individual ditengah persaingan yang begitu ketat dalam mencapai tujuan tertentu, kenyataan inilah yang membuat nilai-nilai sosial ditatanan masyarakat yang sejak dulu sudah ditanamkan oleh nenek moyang kita luntur seiring dengan perkembangan jaman. padahal untuk mencapai suatu tujuan dan cita-cita bersama seharusnya dikerjakan secara bersama-sama.&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Maka dengan kenyataan inilah, pemerintah desa senggigi kembali melakukan sebuah inovasi baru dalam merangkul masyarakat agar terus menanamkan kebudayaan \"Gotong Raoyong\". kegitan gotong royong dalam pembangunan jalan desa sedikitnya melibatkan hampir 95% masyarakat senggigi, kebersamaan dan ikatan persaudaraan atas kepentingan bersama menjadi satu ketika semua masyarakat desa terlibat aktif, tanpa harus melihat tatanan dan golongan yang ada. masyarakat saling bahu membahu seiring kegitan gotong royong.&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>', 1, '2016-08-24 11:02:44', 1, 1, 'Membangun Desa Lewat Gotong Royong', 0, '1472782825artikel-2-2.jpeg', '1472007764', '1472007764', '', '', 1, 'membangun-desa-lewat-gotong-royong', 14, 1, NULL, 3, 1, 'dinamis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (95, 1, '1527540313_kemerdekaan-pantai.jpg', '<p>Desa Senggigi ikut memeriahkan perayaan 17 Agustus 2016 sebagai hari jadi Indonesia yang ke 71 melalui kegiatan Karnaval yang diselenggarakan oleh Camat Batulayar Kabupaten Lombok Barat NTB. Acara karnaval dilaksanakan pada hari Rabu, 17 Agustus 2016 dimulai pukul 15.30 s/d 17.00 wita. Masing-masing desa berkumpul disekitaran kantor Camat Batulayar, dan berjalan menuju Taman Bale Pelangi Desa Sandik sebagai pusat titik kumpul seluruh peserta karnaval.&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Dalam karnaval ini, Desa Senggigi melibatkan berbagai unsur masyarakat seperti tokoh masyarakat, perempuan, pemuda dan anak-anak dengan menggunakan baju adat dan berbagai macam asesoris hari kemerdekaan, kegitan tersebut adalah salah satu cara bagaimana memupuk semangat bagi setiap warga negara, khususnya kaum muda sebagai harapan bangsa, yang kian hari semakin terkikis dengan pengaruh global saat ini.</p>\r\n<p>&nbsp;</p>\r\n<p>Lewat karang taruna desa senggigi, pemupukan pemberian semangat dalam berpacu memajukan desa dan bangsa terus dilakukan, berbagai macam kegiatan tahapan dalam pelaksanaan hari kemerdekaan terus di lakukan.&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', 1, '2016-08-24 13:05:21', 1, 1, 'Perayaan Hari Kemerdekaan 2016', 0, '1472782634galeri-1-2.jpeg', '1472015120', '1472015120', '', '', 1, 'perayaan-hari-kemerdekaan-2016', 18, 1, NULL, 3, 1, 'dinamis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (96, 1, '1472782915artikel-3-1.jpeg', '<p>Dalam rapat pembahasan komitmen perekrutan karyawan hotel pada tanggal 24 Agustus 2016 di kantor desa sengigi telah menyepakati beberapa komitmen bersama diantaranya sebagai berikut:</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>1. Dalam perekrutan karyawan, pihak hotel harus memprioritaskan masyarakat senggigi minimal 35%</p>\n<p>2. Pihak Hotel harus mengikuti program perencanaan tenaga kerja desa senggigi sesua dengan VISI dan MISI desa</p>\n<p>3. Pihak hotel harus melakukan kordinasi dengan pemerintah desa ketika perekrutan karyawan&nbsp;</p>\n<p>4. Pihak Hotel harus melakukan pelatihan bagi calon karyawan, khususnya karyawan yang berasal dari desa sengggigi</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>Bagi rekan-rekan pemuda dan masyarakat harap melakukan kordinasi dengan pemerintah desa terkait dengan beberapa hasil pertemuan dalam membangun komitme dengan pihak hotel, jika ada hal mendesak terkait beberapa syarat ketentuan perekrutan, rekan-rekan pemuda dan masyarakat bisa menghubungi kami di kantor desa..</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>', 1, '2016-08-24 13:55:10', 4, 1, 'Rapat membangun Komitmen antara Karang Taruna Desa Senggigi dengan Taruna Hotel', 0, '1472018109IMG-20160824-WA0000.jpg', '1472018109', '1472018109', '', '', 1, 'rapat-membangun-komitmen-antara-karang-taruna-desa-senggigi-dengan-taruna-hotel', 16, 1, NULL, 3, 0, 'dinamis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (97, 1, '1472019299', '<p>Halaman ini berisi tautan menuju informasi mengenai Basis Data Desa. Ada dua jenis data yang dimuat dalam sistem ini, yakni basis data kependudukan dan basis data sumber daya desa. Sila klik pada tautan berikut untuk mendapatkan tampilan data statistik per kategori.</p>\r\n<ol>\r\n<li>Data Wilayah Administratif&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; &nbsp;</li>\r\n<li>Data Pendidikan&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; &nbsp;</li>\r\n<li>Data Pekerjaan&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; &nbsp;</li>\r\n<li>Data Golongan Darah&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; &nbsp;</li>\r\n<li>Data Agama&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; &nbsp;</li>\r\n<li>Data Jenis Kelamin&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; &nbsp;</li>\r\n<li>Data Kelompok Umur&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; &nbsp;</li>\r\n<li>Data Penerima Raskin&nbsp;&nbsp; &nbsp; &nbsp;&nbsp; &nbsp;</li>\r\n<li>Data Penerima BPJS &nbsp; &nbsp; &nbsp; &nbsp;</li>\r\n<li>Data Warga Negara &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp;&nbsp;</li>\r\n</ol>\r\n<p>Data yang tampil adalah statistik yang didapatkan dari proses olah data dasar yang dilakukan secara&nbsp;<em>offline</em>&nbsp;di kantor desa secara rutin/harian. Data dasar di kantor desa diunggah ke dalam sistem&nbsp;<em>online</em>&nbsp;di website ini secara berkala. Sila hubungi kontak pemerintah desa untuk mendapatkan data dan informasi desa termutakhir.</p>', 1, '2016-08-24 14:14:59', NULL, 1, 'Data Desa', 0, '1472019299', '1472019299', '1472019299', '', '', 1, 'data-desa', 38, 1, NULL, 3, 0, 'statis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (98, 1, '1549419108_desa.jpg', '<p>Wilayah desa berisi tentang penjelasan dan deskripsi letak wilayah desa. contohnya sebagai berikut :<br />Batas-batas :<br />Utara&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Kelurahan a<br />Timur &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: Desa b<br />Selatan&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Desa c<br />Barat&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Kelurahan d dan Desa e<br />Luas Wilayah Desa Penglatan&nbsp;&nbsp; : 186,193 Ha<br />Letak Dan Batas Desa x<br />Desa Penglatan terletak pada posisi 115. 7.20 LS 8. 7.10 BT, dengan ketinggian kurang lebih 250 M diatas permukaan laut.</p>\r\n<p>Peta Desa:</p>\r\n<p><iframe src=\"https://www.google.co.id/maps?f=q&amp;source=s_q&amp;hl=en&amp;geocode=&amp;q=Logandu,+Karanggayam&amp;aq=0&amp;oq=logandu&amp;sll=-2.550221,118.015568&amp;sspn=52.267573,80.332031&amp;t=h&amp;ie=UTF8&amp;hq=&amp;hnear=Logandu,+Karanggayam,+Kebumen,+Central+Java&amp;z=14ÃƒÂ¢Ã¢â‚¬Â°Ã‚Âª=-7.55854,109.634173&amp;output=embed\" width=\"600\" height=\"450\" frameborder=\"0\" marginwidth=\"0\" marginheight=\"0\" scrolling=\"no\"></iframe></p>', 1, '2016-08-26 14:28:14', NULL, 1, 'Wilayah Desa', 0, '1472192894', '1472192894', '1472192894', '', '', 1, 'wilayah-desa', 19, 1, NULL, 3, 0, 'statis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (99, 1, '1472228892Raja Lombok 1902.jpg', '<p style=\"text-align: justify;\" align=\"center\">SEjarah telah mencatat bahwa Pulau Lombok pernah menjadi wilayah kekuasaan Kerajaan Karang Asem Bali yang berkedudukan di Cakranegara dengan seorang raja bernama Anak Agung Gde Jelantik. Berakhirnya <strong>kekuasaan</strong> Kerajaan Karang Asem Bali di Pulau Lombok setelah datangnya Belanda pada Tahun 1891, dimana Belanda pada waktu itu ingin menguasai Pulau Lombok dengan dalih pura-pura membantu rakyat Lombok yang dianggap tertindas oleh Pemerintahan Raja Lombok yaitu Anak Agung Gede Jelantik.</p>\r\n<p style=\"text-align: justify;\">Pada masa kekuasaan Raja Lombok yaitu Anak Agung Gde Jelantik, wilayah Desa Senggigi ( Dusun Mangsit, Kerandangan, Senggigi dan Dusun Loco) masih bergabung dengan Desa Senteluk yang sekarang menjadi Desa Meninting . Sedangkan pada tahun 1962 Desa Senteluk pecah menjadi 2 (Dua) desa yaitu Desa Meninting dan Desa Batulayar dan Dusun Mangsit,Kerandangan,Senggigi dan Dusun Loco bergabung ke Desa Batulayar.&nbsp;</p>\r\n<p style=\"text-align: justify;\">Pemberian nama Desa Batulayar pada waktu itu yang lazim disebut dengan Pemusungan/Kepala Dea Batulayar berdasarkan hasil musyawarah nama Batulayar diambil dari nama tempat yang amat terkenal yaitu Makam Batulayar yang sampai saat ini banyak dikunjungi oleh masyarakat Pulau Lombok pada khususnya dan Masyarakat Nusa Tenggara Barat pada umumnya.</p>\r\n<p style=\"text-align: justify;\">Pada tahun 2001 Desa Batulayar dimekarkan menjadi 2 (dua) yaitu Desa Batulayar (sebagai Desa Induk) dan Desa Senggigi (sebagai Desa Persiapan) dengan SK.Bupati No : 30 Tahun 2001 tanggal 17 Mei 2001, yang pada waktu itu yang menjadi pejabat Kepala Desa Senggigi ialah <strong>H. ARIF RAHMAN, S.IP</strong>., dengan jumlah dusun sebanyak 3 dusun, yaitu :</p>\r\n<p>1. Dusun Senggigi</p>\r\n<p>2. Dusun Kerandangan</p>\r\n<p>3. Dusun Mangsit</p>\r\n<p>Selanjutnya pada tanggal 30 Juli 2003 Pejabat Kepala Desa Senggigi dari <strong>H. ARIF RAHMAN, S.IP</strong> diganti oleh Saudara<strong> ARIFIN</strong> dengan SK. Bupati Lombok Barat No : 409/66/pem/2003. Berhubung Desa Senggigi masih bersifat Desa Persiapan, maka berdasarkan hasil musyawarah desa, tertanggal 15 Desember 2003 , maka pada tanggal 22 Desember 2003 Desa Senggigi mengadakan Pemilihan Kepala Desa devinitif yang pertama kali dipimpin oleh&nbsp;<strong>HAJI JUNAIDI</strong>&nbsp;terpilih&nbsp;dengan SK. Bupati Lombok Barat No :01/01/Pem/2004 tertanggal 2 Januari 2004&nbsp;sampai pada tahun 2008.&nbsp;</p>\r\n<p style=\"text-align: justify;\">Selanjutnya pada tahun 2008, Desa Senggigi mengadakan pemilihan Kepala Desa Senggigi yang kedua dan dimenangkan oleh Bapak <strong>H. MUTAKIR AHMAD</strong>&nbsp;dengan&nbsp;SK. Bupati Lombok Barat No :1320/48/Pem./2008 tertanggal 23 Desember 2008, Periode 2008-2014. &nbsp;Kemudian Kepala desa terpilih Periode 2015 s/d 2021&nbsp;adalah <strong>MUHAMMAD ILHAM</strong>&nbsp;dengan SK. Bupati Lombok Barat No : 160/04/BPMPD/15 tanggal 27 Januari 2015 kini baru menjabat 2 (dua) bulan.</p>\r\n<p style=\"text-align: justify;\">Demikian selanyang pandang atau sejarah singkat Desa Senggigi yang dapat kami sampaikan kepada para pegiat Medsos, semoga dapat bermanfaat untuk kita semua, terima kasih.</p>\r\n<p style=\"text-align: justify;\" align=\"center\">&nbsp;</p>\r\n<p style=\"text-align: justify;\" align=\"center\">&nbsp;</p>', 1, '2016-08-26 15:38:09', NULL, 1, 'Sejarah Desa', 0, '1472229325490125_20121123041539.jpg', '1472197089', '1472197089', '', '', 1, 'sejarah-desa', 31, 1, NULL, 3, 1, 'statis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (100, 1, NULL, '<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"https://note.mhsblogs.unair.ac.id/wp-content/uploads/sites/65/2023/10/industri-kuliner-dan-pariwisata.webp\" alt=\"\" width=\"773\" height=\"451\"></p>\r\n<p><a href=\"https://note.mhsblogs.unair.ac.id/?p=84\">Pariwisata berbasis kuliner</a> telah menjadi tren global yang mendapatkan perhatian yang semakin besar. Desa-desa yang kaya akan warisan kuliner mereka memiliki potensi besar untuk mengembangkan sektor pariwisata dan menggerakkan ekonomi lokal. Artikel ini akan membahas potensi desa dan pariwisata berbasis kuliner, serta bagaimana pengembangan sektor ini dapat memberikan manfaat ekonomi dan sosial bagi masyarakat lokal.</p>\r\n<h2><strong>1. Keunikan Kuliner Desa sebagai Daya Tarik Pariwisata</strong></h2>\r\n<p>Desa-desa seringkali memiliki keunikan kuliner yang sulit ditemukan di tempat lain. Setiap desa memiliki resep tradisional dan bahan baku lokal yang menciptakan keanekaragaman rasa. Pariwisata berbasis kuliner memungkinkan wisatawan untuk merasakan kelezatan autentik dari setiap daerah, menciptakan pengalaman yang tak terlupakan.</p>\r\n<h2><strong>2. Pengembangan Usaha Kuliner Lokal</strong></h2>\r\n<p>Dengan meningkatnya minat terhadap kuliner lokal, desa-desa dapat mengembangkan usaha kuliner mereka. Ini mencakup pembuatan produk makanan lokal yang dapat dijual kepada wisatawan sebagai oleh-oleh khas daerah. Koperasi petani dan pengusaha kuliner lokal dapat bekerja sama untuk menciptakan nilai tambah pada produk mereka.</p>\r\n<h2><strong>3. Pelatihan dan Pendidikan Kuliner</strong></h2>\r\n<p>Pengembangan pariwisata berbasis kuliner juga membuka peluang untuk pelatihan dan pendidikan kuliner. Masyarakat lokal dapat dilibatkan dalam program pelatihan untuk meningkatkan keterampilan kuliner mereka, menciptakan peluang kerja lokal, dan mempromosikan keberlanjutan dalam produksi makanan.</p>\r\n<h2><strong>4. Festival Kuliner Desa</strong></h2>\r\n<p>Penting untuk menciptakan acara-acara tahunan, seperti festival kuliner desa, untuk menarik wisatawan. Festival ini dapat menjadi platform untuk memamerkan kekayaan kuliner lokal, mengundang chef terkenal, dan menciptakan atmosfer meriah yang dapat menarik perhatian media dan wisatawan.</p>\r\n<h2><strong>5. Peningkatan Infrastruktur Pariwisata</strong></h2>\r\n<p>Pengembangan pariwisata berbasis kuliner memerlukan investasi dalam infrastruktur pariwisata, seperti pengembangan jalur wisata kuliner, peningkatan aksesibilitas, dan pembangunan akomodasi. Ini akan membantu meningkatkan daya tarik desa sebagai destinasi wisata kuliner.</p>\r\n<h2><strong>6. Pelestarian Budaya dan Lingkungan</strong></h2>\r\n<p>Pariwisata berbasis kuliner dapat menjadi alat untuk melestarikan budaya lokal dan mendorong praktik pertanian berkelanjutan. Masyarakat dapat mempertahankan tradisi kuliner mereka sambil memanfaatkan bahan baku lokal, yang pada gilirannya dapat mendukung keberlanjutan lingkungan.</p>\r\n<h2><strong>7. Dampak Positif bagi Ekonomi Lokal</strong></h2>\r\n<p>Pariwisata berbasis kuliner bukan hanya memberikan manfaat bagi wisatawan, tetapi juga dapat menciptakan lapangan kerja dan meningkatkan pendapatan masyarakat setempat. Pengembangan usaha kuliner lokal dapat meningkatkan daya beli masyarakat, menciptakan ekosistem ekonomi yang berkelanjutan.</p>\r\n<h2><strong>Kesimpulan</strong></h2>\r\n<p>Pariwisata berbasis kuliner memiliki potensi besar untuk mengubah desa-desa menjadi destinasi yang menarik. Dengan memanfaatkan keunikan kuliner lokal, melibatkan masyarakat dalam pengembangan, dan mempromosikan keberlanjutan, desa-desa dapat meraih manfaat ekonomi yang signifikan. Pariwisata kuliner bukan hanya tentang mencicipi makanan, tetapi juga tentang menciptakan pengalaman berharga yang melibatkan budaya, tradisi, dan keindahan alam lokal.</p>', 1, '2023-12-15 09:52:46', 20, 1, 'Memanfaatkan Potensi Desa dan Pariwisata Berbasis Kuliner untuk Pengembangan Ekonomi Lokal', 1, NULL, NULL, NULL, NULL, '', 1, 'memanfaatkan-potensi-desa-dan-pariwisata-berbasis-kuliner-untuk-pengembangan-ekonomi-lokal', 26, 1, NULL, 3, 0, 'dinamis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (101, 1, NULL, '<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"https://img.freepik.com/free-photo/technology-human-touch-background-modern-remake-creation-adam_53876-129794.jpg?w=1380&amp;t=st=1702610383~exp=1702610983~hmac=06d29ac40c1043de8fd1d5094df33a897314b48fe73c9182cfa37feb8e90406c\" alt=\"\" width=\"828\" height=\"552\"></p>\r\n<p>Dalam era digital yang terus berkembang, Kecerdasan Buatan (AI) telah menjadi kekuatan pendorong utama di berbagai sektor, termasuk ekonomi lokal. Pemanfaatan teknologi AI dapat memberikan kontribusi yang signifikan terhadap pertumbuhan ekonomi di tingkat lokal, menciptakan peluang baru, meningkatkan efisiensi, dan menciptakan ekosistem bisnis yang inovatif.</p>\r\n<h2><strong>1. Peningkatan Produktivitas dan Efisiensi Operasional</strong></h2>\r\n<p>Implementasi teknologi AI dapat meningkatkan produktivitas dan efisiensi operasional di berbagai sektor ekonomi lokal. Sistem otomatisasi yang didukung oleh AI dapat membantu dalam mengelola inventaris, proses produksi, dan rantai pasok, mengurangi kesalahan manusia dan meningkatkan akurasi.</p>\r\n<h2><strong>2. Analisis Data untuk Pengambilan Keputusan yang Lebih Baik</strong></h2>\r\n<p>Teknologi AI memungkinkan pengumpulan dan analisis data yang cepat dan akurat. Dengan memahami tren pasar, perilaku konsumen, dan kebutuhan bisnis, pemangku kepentingan lokal dapat membuat keputusan yang lebih baik. Ini membantu dalam merancang strategi bisnis yang lebih tepat sasaran dan responsif terhadap perubahan pasar.</p>\r\n<h2><strong>3. Penciptaan Lapangan Kerja dalam Industri AI</strong></h2>\r\n<p>Pengembangan dan penerapan teknologi AI menciptakan kebutuhan baru akan keahlian teknis. Oleh karena itu, pelatihan dan pendidikan untuk keahlian AI dapat membuka peluang baru dalam penciptaan lapangan kerja lokal. Hal ini dapat meningkatkan tingkat pekerjaan di komunitas dan memajukan kualitas tenaga kerja lokal.</p>\r\n<h2><strong>4. Pemajuan Ekosistem Startup Lokal</strong></h2>\r\n<p>AI mendorong inovasi, dan banyak perusahaan startup lokal dapat memanfaatkannya untuk menciptakan solusi-solusi baru. Dukungan untuk ekosistem startup AI lokal dapat menciptakan lingkungan yang mendukung kreativitas dan pemecahan masalah lokal, sehingga mendorong pertumbuhan bisnis yang berkelanjutan.</p>\r\n<h2><strong>5. Peningkatan Pengalaman Pelanggan</strong></h2>\r\n<p>Dalam sektor layanan, AI digunakan untuk meningkatkan pengalaman pelanggan. <a href=\"https://optimasi.co/digital-marketing/maksimalkan-bisnis-dengan-chatbot-commerce/33018/\">Chatbot, personalisasi layanan</a>, dan analisis prediktif dapat meningkatkan interaksi antara pelanggan dan bisnis lokal. Hal ini tidak hanya menciptakan loyalitas pelanggan, tetapi juga meningkatkan reputasi bisnis di komunitas.</p>\r\n<h2><strong>6. Pemantauan dan Pengelolaan Sumber Daya Alam</strong></h2>\r\n<p>Dalam sektor pertanian dan lingkungan, AI dapat digunakan untuk pemantauan dan pengelolaan sumber daya alam secara berkelanjutan. Sistem pemantauan tanaman, prediksi cuaca, dan manajemen air yang berbasis AI dapat membantu petani lokal meningkatkan hasil panen dan menjaga keberlanjutan lingkungan.</p>\r\n<h2><strong>7. Pembangunan Smart Cities dan Konektivitas</strong></h2>\r\n<p>Penerapan AI dalam pengembangan kota pintar (smart cities) dapat meningkatkan infrastruktur dan konektivitas di tingkat lokal. Sistem transportasi pintar, manajemen limbah yang efisien, dan pemantauan keamanan berbasis AI dapat menciptakan lingkungan yang lebih aman, bersih, dan nyaman untuk penduduk setempat.</p>\r\n<h2><strong>Kesimpulan</strong></h2>\r\n<p>Memanfaatkan kecerdasan buatan untuk pertumbuhan ekonomi lokal bukan hanya tentang adopsi teknologi, tetapi juga tentang menciptakan ekosistem yang mendukung inovasi, pelatihan tenaga kerja, dan pengembangan bisnis lokal. Dengan langkah-langkah yang tepat, integrasi AI dapat menjadi kekuatan positif yang mengubah lanskap ekonomi lokal, menciptakan peluang baru, dan meningkatkan kesejahteraan masyarakat secara keseluruhan.</p>', 1, '2023-12-01 10:22:51', 20, 1, 'Memanfaatkan Kecerdasan Buatan (AI) untuk Mendorong Pertumbuhan Ekonomi Lokal', 0, NULL, NULL, NULL, NULL, '', 1, 'memanfaatkan-kecerdasan-buatan-ai-untuk-mendorong-pertumbuhan-ekonomi-lokal', 27, 1, NULL, 3, 0, 'dinamis');
INSERT INTO `artikel` (`id`, `config_id`, `gambar`, `isi`, `enabled`, `tgl_upload`, `id_kategori`, `id_user`, `judul`, `headline`, `gambar1`, `gambar2`, `gambar3`, `dokumen`, `link_dokumen`, `boleh_komentar`, `slug`, `hit`, `tampilan`, `urut`, `jenis_widget`, `slider`, `tipe`) VALUES (102, 1, NULL, '<p>Sewa motor di Yogyakarta, atau <a href=\"https://www.tujuhrupa.com/2023/11/jelajah-jogja-dengan-sewa-motor.html\">Sewa Motor Jogja</a>, memberikan alternatif transportasi yang populer di kalangan para wisatawan yang ingin menjelajahi keindahan kota ini dengan lebih leluasa. Dengan banyaknya penyedia jasa sewa motor yang tersebar di berbagai penjuru Yogyakarta, pelancong dapat dengan mudah menemukan sepeda motor yang sesuai dengan preferensi dan kebutuhan perjalanan mereka. Opsi sewa motor tidak hanya memberikan kebebasan untuk menentukan rute perjalanan sendiri, tetapi juga memberikan fleksibilitas dalam menjelajahi tempat-tempat wisata, situs sejarah, dan keunikan budaya yang dimiliki oleh kota istimewa ini.</p>\r\n<p>Keunggulan utama dari Sewa Motor Jogja adalah kemudahan dan kenyamanan yang ditawarkannya kepada wisatawan. Dengan biaya sewa yang relatif terjangkau, wisatawan dapat mengakses berbagai destinasi tanpa harus terikat pada jadwal transportasi umum. Para penyedia jasa sewa motor biasanya menyediakan berbagai jenis sepeda motor, mulai dari yang ekonomis hingga yang lebih bertenaga, sehingga pelancong dapat memilih kendaraan yang paling sesuai dengan kebutuhan mereka selama berada di Yogyakarta.</p>\r\n<p>Selain memberikan keleluasaan dalam perjalanan, Sewa Motor Jogja juga memberikan pengalaman yang lebih pribadi dan autentik. Wisatawan dapat mengeksplorasi sudut-sudut kota yang mungkin tidak terjangkau oleh transportasi umum, menemukan warung-warung makan lokal, dan berinteraksi langsung dengan masyarakat setempat. Dengan menggunakan sepeda motor, mereka dapat merasakan getaran budaya dan kehidupan sehari-hari Yogyakarta dengan lebih mendalam, menciptakan kenangan yang tak terlupakan selama perjalanan mereka di kota istimewa ini.</p>', 1, '2023-11-01 10:48:00', 20, 1, 'Sewa Motor Jogja: Petualangan Bebas dan Personal Menjelajahi Keindahan Kota Istimewa', 0, NULL, NULL, NULL, NULL, '', 1, 'sewa-motor-jogja-petualangan-bebas-dan-personal-menjelajahi-keindahan-kota-istimewa', 24, 1, NULL, 3, 0, 'dinamis');
