INSERT INTO `log_surat` (`id`, `config_id`, `id_format_surat`, `id_pend`, `id_pamong`, `nama_pamong`, `nama_jabatan`, `id_user`, `tanggal`, `bulan`, `tahun`, `no_surat`, `nama_surat`, `lampiran`, `nik_non_warga`, `nama_non_warga`, `keterangan`, `lokasi_arsip`, `urls_id`, `status`, `log_verifikasi`, `tte`, `verifikasi_operator`, `verifikasi_kades`, `verifikasi_sekdes`, `isi_surat`, `kecamatan`, `deleted_at`, `pemohon`, `input`) VALUES (7, 1, 2, 1, 14, 'Muhammad Ilham ', 'Kepala Desa', 1, '2019-03-30 10:36:04', '03', '2019', '1', 'surat_ket_penduduk_5201142005716996_2019-03-30_1.rtf', '', NULL, NULL, NULL, '', NULL, 1, NULL, NULL, 1, 1, 1, NULL, 1, NULL, NULL, NULL);
INSERT INTO `log_surat` (`id`, `config_id`, `id_format_surat`, `id_pend`, `id_pamong`, `nama_pamong`, `nama_jabatan`, `id_user`, `tanggal`, `bulan`, `tahun`, `no_surat`, `nama_surat`, `lampiran`, `nik_non_warga`, `nama_non_warga`, `keterangan`, `lokasi_arsip`, `urls_id`, `status`, `log_verifikasi`, `tte`, `verifikasi_operator`, `verifikasi_kades`, `verifikasi_sekdes`, `isi_surat`, `kecamatan`, `deleted_at`, `pemohon`, `input`) VALUES (12, 1, 220, 9, 20, 'Mustahiq S.Adm', 'Kepala Desa', 1, '2023-12-15 17:08:59', '12', '2023', '1', 'surat-permohonan-kartu-keluarga_5201140107867064_2023-12-15_1.pdf', NULL, NULL, NULL, '-', '', 5, 1, NULL, NULL, 1, 1, 1, '\r\n            <page backtop=\"35mm\" backbottom=\"20mm\">\r\n            <page_header><table style=\"border-collapse: collapse; width: 100%;\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 10%;\"><img src=\"/home/berputar.opendesa.id/public_html/assets/files/logo/opensid_logo.png\" width=\"90\" height=\"90\" alt=\"logo-surat\" /></td>\r\n<td style=\"text-align: center; width: 90%;\">\r\n<p style=\"margin: 0; text-align: center;\"><span style=\"font-size: 14pt;\">PEMERINTAH KABUPATEN PAMEKASAN <br>KECAMATAN WARU<strong><br>DESA WARU BARAT </strong></span></p>\r\n<p style=\"margin: 0; text-align: center;\"><em><span style=\"font-size: 10pt;\">Jl. Raya Senggigi Km 10 Kerandangan Kode Pos: 83355</span></em></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr style=\"border: 3px solid;\"></page_header>\r\n            <page_footer>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 10px;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 11.2886%; height: 10px;\">3528102010</td>\r\n<td style=\"width: 78.3174%; height: 10px;\">\r\n<p style=\"text-align: center;\"> </p>\r\n</td>\r\n<td style=\"width: 10.3939%; height: 10px; text-align: right;\">S-36</td>\r\n</tr>\r\n</tbody>\r\n</table></page_footer>\r\n            \r\n<h4 style=\"margin: 0; text-align: center;\"><span style=\"text-decoration: underline;\">SURAT PERMOHONAN KARTU KELUARGA</span></h4>\r\n<p style=\"margin: 0; text-align: center;\">Nomor : S-36/001/3528102010/XII/2023<br><br></p>\r\n<p style=\"text-align: justify; text-indent: 30px;\">Yang bertanda tangan di bawah ini Kepala Desa Waru Barat, Kecamatan Waru, Kabupaten Pamekasan, Provinsi Jawa Timur menerangkan dengan sebenarnya bahwa :</p>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 270px;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 4.32489%; text-align: center; height: 18px;\"> </td>\r\n<td style=\"width: 3.90295%; height: 18px; text-align: left;\">1.</td>\r\n<td style=\"width: 30.4852%; text-align: left; height: 18px;\">Nama</td>\r\n<td style=\"width: 1.26582%; text-align: center; height: 18px;\">:</td>\r\n<td style=\"width: 60.0211%; height: 18px; text-align: justify;\"><strong>ASHARI</strong></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 4.32489%; text-align: center; height: 18px;\"> </td>\r\n<td style=\"width: 3.90295%; height: 18px; text-align: left;\">2.</td>\r\n<td style=\"width: 30.4852%; text-align: left; height: 18px;\">Tempat / Tanggal Lahir</td>\r\n<td style=\"width: 1.26582%; text-align: center; height: 18px;\">:</td>\r\n<td style=\"width: 60.0211%; height: 18px; text-align: justify;\">KERANDANGAN/30 Desember 1985</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 4.32489%; text-align: center; height: 18px;\"> </td>\r\n<td style=\"width: 3.90295%; height: 18px; text-align: left;\">3.</td>\r\n<td style=\"width: 30.4852%; text-align: left; height: 18px;\">Umur</td>\r\n<td style=\"width: 1.26582%; text-align: center; height: 18px;\">:</td>\r\n<td style=\"width: 60.0211%; height: 18px; text-align: justify;\">37 Tahun</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 4.32489%; text-align: center; height: 18px;\"> </td>\r\n<td style=\"width: 3.90295%; height: 18px; text-align: left;\">4.</td>\r\n<t