INSERT INTO `program` (`id`, `config_id`, `nama`, `slug`, `sasaran`, `kk_level`, `ndesc`, `sdate`, `edate`, `status`, `asaldana`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES (1, 1, 'BPNT', 'bpnt', 2, NULL, 'Program KESOS memberi bantuan sosial pangan dalam bentuk non tunai dari pemerintah yang diberikan kepada KPM setiap bulannya melalui mekanisme akun elektronik yang digunakan hanya untuk membeli bahan pangan di pedagang bahan pangan/e-warong yang bekerjasama dengan bank.', '2015-12-13', '2021-12-13', 0, 'Pusat', '2023-12-15 01:47:42', 1, '2023-12-15 07:38:50', 1);
INSERT INTO `program` (`id`, `config_id`, `nama`, `slug`, `sasaran`, `kk_level`, `ndesc`, `sdate`, `edate`, `status`, `asaldana`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES (2, 1, 'BLSM', 'blsm', 2, NULL, 'Bantuan Langsung Sementara Masyarakat atau BLSM (kadang disebut juga balsem) adalah bantuan yang diberikan Pemerintah Indonesia menyambut kenaikan harga BBM yang terjadi pada 22 Juni 2013 pada jam 00.00', '2015-12-13', '2017-12-13', 0, 'Pusat', '2023-12-15 01:47:42', 1, '2023-12-15 01:47:55', 1);
INSERT INTO `program` (`id`, `config_id`, `nama`, `slug`, `sasaran`, `kk_level`, `ndesc`, `sdate`, `edate`, `status`, `asaldana`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES (3, 1, 'PKH', 'pkh', 2, NULL, 'Program Keluarga Harapan yang selanjutnya disebut PKH adalah program pemberian bantuan sosial bersyarat kepada Keluarga Miskin (KM) yang ditetapkan sebagai keluarga penerima manfaat PKH.\r\n\r\nSebagai sebuah program bantuan sosial bersyarat, PKH membuka akses keluarga miskin terutama ibu hamil dan anak untuk memanfaatkan berbagai fasilitas layanan kesehatan (faskes) dan fasilitas layanan pendidikan (fasdik) yang tersedia di sekitar mereka.', '2015-12-13', '2022-12-13', 0, 'Pusat', '2023-12-15 01:47:42', 1, '2023-12-15 07:38:50', 1);
INSERT INTO `program` (`id`, `config_id`, `nama`, `slug`, `sasaran`, `kk_level`, `ndesc`, `sdate`, `edate`, `status`, `asaldana`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES (4, 1, 'Bedah Rumah', 'bedah-rumah', 2, NULL, 'Bantuan Stimulan Perumahan Swadaya (BSPS). Program ini lebih dikenal sebagai program Bedah Rumah.\r\n\r\nKementrian Pekerjaan Umum dan Perumahan Rakyat (KemenPUPR) menjalankan BSPS untuk membantu Masyarakat Berpenghasilan Rendah (MBR), agar dapat memiliki rumah yang layak huni.', '2015-12-13', '2021-12-13', 0, 'Pusat', '2023-12-15 01:47:42', 1, '2023-12-15 07:38:50', 1);
INSERT INTO `program` (`id`, `config_id`, `nama`, `slug`, `sasaran`, `kk_level`, `ndesc`, `sdate`, `edate`, `status`, `asaldana`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES (5, 1, 'JAMKESMAS', 'jamkesmas', 1, NULL, 'Jamkesmas ( akronim dari Jaminan Kesehatan Masyarakat ) adalah sebuah program jaminan kesehatan untuk warga Indonesia yang memberikan perlindungan sosial dibidang kesehatan untuk menjamin masyarakat miskin dan tidak mampu yang iurannya dibayar oleh pemerintah agar kebutuhan dasar kesehatannya yang layak dapat terpenuhi.Program ini dijalankan oleh Departemen Kesehatan sejak 2008.', '2023-12-15', '2023-12-31', 0, 'Pusat', '2023-12-15 01:47:42', 1, '2024-01-02 03:34:27', 1);
INSERT INTO `program` (`id`, `config_id`, `nama`, `slug`, `sasaran`, `kk_level`, `ndesc`, `sdate`, `edate`, `status`, `asaldana`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES (6, 1, 'Bantuan Sosial Tunai', 'bantuan-sosial-tunai', 1, NULL, 'Bantuan Kementerian Sosial Republik Indonesia', '2023-12-15', '2023-12-31', 0, 'Pusat', '2023-12-15 15:48:26', NULL, '2024-01-02 03:34:27', NULL);
INSERT INTO `program` (`id`, `config_id`, `nama`, `slug`, `sasaran`, `kk_level`, `ndesc`, `sdate`, `edate`, `status`, `asaldana`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES (7, 1, 'hhh', 'hhh', 3, NULL, 'uu', '2023-12-15', '2023-12-23', 0, 'Kab/Kota', '2023-12-15 16:41:16', NULL, '2023-12-24 01:36:46', NULL);
